// Machine-neutral profile geometry, not DSTV or machine instructions. All lengths mm.
// Datum: lower bounds of section and earliest physical end along the extrusion axis.
import {validateNotches} from './notch-engine.mjs';
const dot=(a,b)=>a.reduce((s,x,i)=>s+x*b[i],0),add=(a,b)=>a.map((x,i)=>x+b[i]),sub=(a,b)=>a.map((x,i)=>x-b[i]),mul=(a,s)=>a.map(x=>x*s),cross=(a,b)=>[a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]];
const vec=(a,n=3)=>Array.isArray(a)&&a.length===n&&a.every(Number.isFinite),unit=a=>vec(a)&&Math.abs(Math.hypot(...a)-1)<1e-7;
const close=(a,b,t=1e-7)=>vec(a,b.length)&&a.every((x,i)=>Math.abs(x-b[i])<=t);
function assert(ok,msg){if(!ok)throw Error(msg)}
function frame(f){assert(f&&vec(f.origin)&&[f.x,f.y,f.z].every(unit)&&Math.abs(dot(f.x,f.y))<1e-7&&Math.abs(dot(f.x,f.z))<1e-7&&Math.abs(dot(f.y,f.z))<1e-7&&dot(cross(f.x,f.y),f.z)>1-1e-7,'מערכת צירים מקומית אינה תקינה');return f;}
const axes=f=>[f.x,f.y,f.z];const local=(f,p)=>axes(f).map(a=>dot(a,sub(p,f.origin)));const direction=(f,p)=>axes(f).map(a=>dot(a,p));const world=(f,p)=>p.reduce((v,x,i)=>add(v,mul(axes(f)[i],x)),f.origin);const worldDir=(f,p)=>p.reduce((v,x,i)=>add(v,mul(axes(f)[i],x)),[0,0,0]);
const area=r=>r.reduce((s,p,i)=>{let q=r[(i+1)%r.length];return s+p[0]*q[1]-p[1]*q[0]},0)/2;
function ring(r){assert(Array.isArray(r)&&r.length>=3&&r.every(p=>vec(p,2))&&Math.abs(area(r))>1e-8,'חתך לא תקין');return r;}
function ends(p,q){let z=p.endPlanes.map(c=>{let n=direction(p.frame,c.normal),v=local(p.frame,c.origin);assert(Math.abs(n[2])>1e-8,'מישור קצה מקביל לציר');return v[2]-(n[0]*(q[0]-v[0])+n[1]*(q[1]-v[1]))/n[2];});assert(z[0]<z[1],'קצוות מתהפכים בחתך');return z;}
export function profileOperations(p){assert(p&&!p.plate&&!p.warnings?.length&&p.id&&p.profile&&p.material,'חלק חסום או לא פרופיל');frame(p.frame);const outer=ring(p.section.outer),inner=(p.section.inners||[]).map(ring);assert(p.endPlanes?.length===2&&p.endPlanes.every(c=>vec(c.origin)&&unit(c.normal)&&['positive','negative'].includes(c.keep)),'מישורי קצה חסרים');assert(p.endPlanes.every((c,i)=>Math.sign(dot(c.normal,p.frame.z))*(c.keep==='positive'?1:-1)===(i===0?1:-1)),'כיוון שמירת חומר שגוי');const zs=outer.map(q=>ends(p,q)),z0=Math.min(...zs.flat()),z1=Math.max(...zs.flat());const off=[Math.min(...outer.map(q=>q[0])),Math.min(...outer.map(q=>q[1])),z0],f={...p.frame,origin:world(p.frame,off)};const shift=r=>r.map(q=>sub(q,off.slice(0,2)));const drills=(p.drills||[]).map(d=>{assert(d.id&&vec(d.center)&&unit(d.axis)&&unit(d.slotAxis)&&Number.isFinite(d.diameter)&&d.diameter>0&&Number.isFinite(d.halfDepth)&&d.halfDepth>0&&Number.isFinite(d.slotExtra||0)&&(d.slotExtra||0)>=0,'קדח לא תקין');if(d.slotExtra)assert(Math.abs(dot(d.axis,d.slotAxis))<1e-7,'כיוון חריץ אינו במישור הקדח');return {id:d.id,center:local(f,d.center),axis:direction(f,d.axis),diameter:d.diameter,halfDepth:d.halfDepth,slotExtra:d.slotExtra||0,slotAxis:direction(f,d.slotAxis)};});assert(new Set(drills.map(d=>d.id)).size===drills.length,'מזהי קדחים כפולים');return {schemaVersion:1,status:'REVIEW_ONLY_NOT_MACHINE_CODE',units:'mm',id:p.id,mark:p.mark,profile:p.profile,family:p.family,material:p.material,datum:f,offset:off,section:{outer:shift(outer),inners:inner.map(shift)},length:z1-z0,sourceLength:p.sourceLength,endPlanes:p.endPlanes.map(c=>({origin:local(f,c.origin),normal:direction(f,c.normal),keep:c.keep})),endStations:zs.map(z=>z.map(v=>v-z0)),drills,notches:validateNotches(p).map(n=>({...n,min:sub(n.min,off),max:sub(n.max,off)}))};}
// Read back into the original local/global frames and compare actual operations, not printed lengths.
export function verifyProfileOperations(p,r){const f=frame(r.datum);assert(r.schemaVersion===1&&r.status==='REVIEW_ONLY_NOT_MACHINE_CODE'&&r.units==='mm'&&['id','mark','profile','family','material','sourceLength'].every(k=>r[k]===p[k]),'זהות חלק אינה תואמת');assert(vec(r.offset)&&close(f.origin,world(p.frame,r.offset))&&axes(f).every((a,i)=>close(a,axes(p.frame)[i])),'אפס או כיוונים שגויים');const compareRing=(a,b)=>a.length===b.length&&a.every((q,i)=>close(add(q,r.offset.slice(0,2)),b[i]));assert(compareRing(r.section.outer,p.section.outer)&&r.section.inners.length===(p.section.inners||[]).length&&r.section.inners.every((q,i)=>compareRing(q,p.section.inners[i])),'חתך אינו תואם');assert(Math.abs(Math.min(...r.section.outer.map(q=>q[0])))<1e-7&&Math.abs(Math.min(...r.section.outer.map(q=>q[1])))<1e-7,'אפס חתך אינו תקין');assert(r.endPlanes.length===2&&r.endPlanes.every((c,i)=>close(world(f,c.origin),p.endPlanes[i].origin)&&close(worldDir(f,c.normal),p.endPlanes[i].normal)&&c.keep===p.endPlanes[i].keep),'מישור חיתוך שונה');assert(r.endStations.length===p.section.outer.length&&r.endStations.every((s,i)=>close(add(s,[r.offset[2],r.offset[2]]),ends(p,p.section.outer[i]))),'תחנות קצה שגויות');assert(Math.abs(Math.min(...r.endStations.flat()))<1e-7&&Math.abs(Math.max(...r.endStations.flat())-r.length)<1e-7,'אורך מעטפת אינו תואם');assert(r.drills.length===(p.drills||[]).length&&r.drills.every((d,i)=>{let b=p.drills[i];return d.id===b.id&&d.diameter===b.diameter&&d.halfDepth===b.halfDepth&&d.slotExtra===(b.slotExtra||0)&&close(world(f,d.center),b.center)&&close(worldDir(f,d.axis),b.axis)&&close(worldDir(f,d.slotAxis),b.slotAxis);}), 'קדח שונה מנתוני המקור');assert(r.notches.length===(p.notches||[]).length&&r.notches.every((n,i)=>n.id===p.notches[i].id&&n.type===p.notches[i].type&&close(add(n.min,r.offset),p.notches[i].min)&&close(add(n.max,r.offset),p.notches[i].max)),'מגרעת שונה');return true;}
export function machiningBatch(parts){const records=[],blocked=[],seen=new Set;for(const p of parts.filter(p=>!p.plate)){try{assert(!seen.has(p.id),'מזהה חלק כפול');seen.add(p.id);let r=JSON.parse(JSON.stringify(profileOperations(p)));verifyProfileOperations(p,r);records.push(r);}catch(e){blocked.push({id:p.id,reason:e.message});}}return {status:'REVIEW_ONLY_NOT_MACHINE_CODE',records,blocked};}
